import sys

def solve():
    input = sys.stdin.readline
    n_line = input().strip()
    if not n_line:
        return
    n = int(n_line)

    grid = [[0] * (n + 1) for _ in range(n + 1)]
    empty_cells = []
    for r in range(1, n + 1):
        for c in range(1, n + 1):
            empty_cells.append((r, c))

    for _ in range(n * n):
        try:
            line = input().strip()
            while not line:
                line = input().strip()
            a = int(line)
        except EOFError:
            break

        if not empty_cells:
            break

        r, c = empty_cells.pop()

        neighbors = []
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 1 <= nr <= n and 1 <= nc <= n and grid[nr][nc] != 0:
                neighbors.append(grid[nr][nc])

        used_colors = set(neighbors)
        used_colors.add(a)

        for b in [1, 2, 3]:
            if b not in used_colors:
                grid[r][c] = b
                print(f"{b} {r} {c}")
                sys.stdout.flush()
                break
        else:
            for b in [1, 2, 3]:
                if b != a:
                    grid[r][c] = b
                    print(f"{b} {r} {c}")
                    sys.stdout.flush()
                    break

if __name__ == "__main__":
    solve()
